# Solidity Smart Contracts: From Basics to Production

Smart contracts are self-executing programs on the blockchain. This guide covers Solidity fundamentals through production-ready patterns.

## Why Solidity?

- **Ethereum Standard**: Most popular smart contract language
- **EVM Compatible**: Works on Ethereum, Polygon, BSC, etc.
- **Rich Ecosystem**: Extensive tools and libraries
- **Battle-Tested**: Powers billions in DeFi

## Solidity Basics

### Contract Structure

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract MyContract {
    // State variables
    address public owner;
    uint256 public value;
    mapping(address => uint256) public balances;

    // Events
    event ValueChanged(uint256 oldValue, uint256 newValue);
    event Deposit(address indexed user, uint256 amount);

    // Modifiers
    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    // Constructor
    constructor(uint256 _initialValue) {
        owner = msg.sender;
        value = _initialValue;
    }

    // Functions
    function setValue(uint256 _newValue) external onlyOwner {
        uint256 oldValue = value;
        value = _newValue;
        emit ValueChanged(oldValue, _newValue);
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }
}
```

### Data Types

```solidity
contract DataTypes {
    // Value Types
    bool public isActive = true;
    uint256 public number = 100;        // 0 to 2^256-1
    int256 public signedNumber = -50;   // -2^255 to 2^255-1
    address public wallet = 0x123...;
    bytes32 public hash;

    // Reference Types
    string public name = "Token";
    bytes public data;
    uint256[] public numbers;

    // Mappings
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => bool)) public approvals;

    // Structs
    struct User {
        string name;
        uint256 balance;
        bool isActive;
    }
    mapping(address => User) public users;

    // Enums
    enum Status { Pending, Active, Completed, Cancelled }
    Status public status = Status.Pending;
}
```

### Visibility and Mutability

```solidity
contract Visibility {
    // State variable visibility
    uint256 public publicVar;     // Readable by anyone
    uint256 internal internalVar; // This contract + derived
    uint256 private privateVar;   // Only this contract

    // Function visibility
    function publicFunc() public { }     // Anyone can call
    function externalFunc() external { } // Only external calls
    function internalFunc() internal { } // This + derived contracts
    function privateFunc() private { }   // Only this contract

    // Function mutability
    function pureFunc(uint a, uint b) public pure returns (uint) {
        return a + b;  // No state access
    }

    function viewFunc() public view returns (uint) {
        return publicVar;  // Read state, no modification
    }

    function payableFunc() public payable {
        // Can receive ETH
    }
}
```

## ERC-20 Token

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MyToken is ERC20, Ownable {
    constructor() ERC20("MyToken", "MTK") Ownable(msg.sender) {
        _mint(msg.sender, 1000000 * 10 ** decimals());
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}
```

## ERC-721 NFT

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MyNFT is ERC721URIStorage, Ownable {
    uint256 private _nextTokenId;
    uint256 public mintPrice = 0.01 ether;
    uint256 public maxSupply = 10000;

    constructor() ERC721("MyNFT", "MNFT") Ownable(msg.sender) {}

    function mint(string memory tokenURI) external payable returns (uint256) {
        require(msg.value >= mintPrice, "Insufficient payment");
        require(_nextTokenId < maxSupply, "Max supply reached");

        uint256 tokenId = _nextTokenId++;
        _safeMint(msg.sender, tokenId);
        _setTokenURI(tokenId, tokenURI);

        return tokenId;
    }

    function withdraw() external onlyOwner {
        payable(owner()).transfer(address(this).balance);
    }
}
```

## Security Best Practices

### Reentrancy Protection

```solidity
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract SecureVault is ReentrancyGuard {
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    // BAD - Vulnerable to reentrancy
    function withdrawUnsafe() external {
        uint256 amount = balances[msg.sender];
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
        balances[msg.sender] = 0;  // State changed after external call!
    }

    // GOOD - Protected with nonReentrant and checks-effects-interactions
    function withdrawSafe() external nonReentrant {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "No balance");

        // Effects before interactions
        balances[msg.sender] = 0;

        // Interaction last
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }
}
```

### Access Control

```solidity
import "@openzeppelin/contracts/access/AccessControl.sol";

contract SecureContract is AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function adminFunction() external onlyRole(ADMIN_ROLE) {
        // Only admins
    }

    function minterFunction() external onlyRole(MINTER_ROLE) {
        // Only minters
    }
}
```

### Safe Math (Built-in since 0.8.0)

```solidity
contract SafeMathExample {
    // Solidity 0.8+ has built-in overflow checks
    function add(uint256 a, uint256 b) public pure returns (uint256) {
        return a + b;  // Reverts on overflow automatically
    }

    // Use unchecked for gas optimization when safe
    function uncheckedIncrement(uint256 i) public pure returns (uint256) {
        unchecked {
            return i + 1;  // No overflow check
        }
    }
}
```

## Gas Optimization

```solidity
contract GasOptimized {
    // Pack variables (uses 1 slot instead of 3)
    struct PackedData {
        uint128 value1;  // 16 bytes
        uint64 value2;   // 8 bytes
        uint64 value3;   // 8 bytes
    }  // Total: 32 bytes = 1 slot

    // Use immutable for values set once
    address public immutable owner;
    uint256 public immutable deployTime;

    constructor() {
        owner = msg.sender;
        deployTime = block.timestamp;
    }

    // Use calldata for read-only arrays
    function processData(uint256[] calldata data) external pure returns (uint256) {
        uint256 sum;
        uint256 length = data.length;  // Cache length

        for (uint256 i; i < length; ) {  // Don't initialize i = 0
            sum += data[i];
            unchecked { ++i; }  // Pre-increment + unchecked
        }
        return sum;
    }

    // Use custom errors (cheaper than require strings)
    error InsufficientBalance(uint256 required, uint256 available);

    function withdraw(uint256 amount) external {
        uint256 balance = address(this).balance;
        if (balance < amount) {
            revert InsufficientBalance(amount, balance);
        }
        // ...
    }
}
```

## Testing with Hardhat

```javascript
// test/MyContract.test.js
const { expect } = require("chai");
const { ethers } = require("hardhat");

describe("MyToken", function () {
    let token, owner, user1, user2;

    beforeEach(async function () {
        [owner, user1, user2] = await ethers.getSigners();

        const MyToken = await ethers.getContractFactory("MyToken");
        token = await MyToken.deploy();
    });

    describe("Deployment", function () {
        it("Should set the right owner", async function () {
            expect(await token.owner()).to.equal(owner.address);
        });

        it("Should mint initial supply to owner", async function () {
            const ownerBalance = await token.balanceOf(owner.address);
            expect(await token.totalSupply()).to.equal(ownerBalance);
        });
    });

    describe("Transfers", function () {
        it("Should transfer tokens", async function () {
            await token.transfer(user1.address, 100);
            expect(await token.balanceOf(user1.address)).to.equal(100);
        });

        it("Should emit Transfer event", async function () {
            await expect(token.transfer(user1.address, 100))
                .to.emit(token, "Transfer")
                .withArgs(owner.address, user1.address, 100);
        });

        it("Should revert if insufficient balance", async function () {
            await expect(
                token.connect(user1).transfer(user2.address, 100)
            ).to.be.revertedWith("ERC20: transfer amount exceeds balance");
        });
    });
});
```

## Deployment Script

```javascript
// scripts/deploy.js
const hre = require("hardhat");

async function main() {
    const [deployer] = await hre.ethers.getSigners();
    console.log("Deploying with:", deployer.address);

    const MyToken = await hre.ethers.getContractFactory("MyToken");
    const token = await MyToken.deploy();
    await token.waitForDeployment();

    const address = await token.getAddress();
    console.log("Token deployed to:", address);

    // Verify on Etherscan
    if (hre.network.name !== "hardhat") {
        console.log("Waiting for confirmations...");
        await token.deploymentTransaction().wait(5);

        await hre.run("verify:verify", {
            address: address,
            constructorArguments: [],
        });
    }
}

main().catch(console.error);
```

## Common Patterns

### Pausable Contract

```solidity
import "@openzeppelin/contracts/utils/Pausable.sol";

contract PausableToken is ERC20, Pausable, Ownable {
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function _update(address from, address to, uint256 value)
        internal override whenNotPaused
    {
        super._update(from, to, value);
    }
}
```

### Upgradeable Contract

```solidity
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";

contract MyTokenV1 is Initializable, ERC20Upgradeable {
    function initialize() public initializer {
        __ERC20_init("MyToken", "MTK");
        _mint(msg.sender, 1000000 * 10 ** decimals());
    }
}
```

## Summary Checklist

### Security
1. ✅ Use ReentrancyGuard for functions with external calls
2. ✅ Follow checks-effects-interactions pattern
3. ✅ Use OpenZeppelin contracts
4. ✅ Implement proper access control
5. ✅ Validate all inputs

### Gas Optimization
1. ✅ Pack struct variables
2. ✅ Use immutable for constants
3. ✅ Use calldata for read-only arrays
4. ✅ Cache array length in loops
5. ✅ Use custom errors

### Testing
1. ✅ Test all functions
2. ✅ Test edge cases
3. ✅ Test access control
4. ✅ Test events
5. ✅ Test reverts

## Conclusion

Smart contract development requires careful attention to security and gas efficiency. Start with OpenZeppelin contracts, test thoroughly, and audit before mainnet deployment.

Happy building on the blockchain!
